int process_ticket_reply(struct ceph_auth_client *ac, struct ceph_crypto_key *secret, void *buf, void *end) {
    size_t remaining = (char *)end - (char *)buf;

    if (!ac || !secret || !buf || !end || remaining <= 0) {
        return -EINVAL;
    }

    if (remaining < sizeof(uint32_t)) {
        return -EINVAL;
    }

    uint32_t *len_ptr = (uint32_t *)buf;
    size_t data_len = *len_ptr;

    if (data_len > remaining - sizeof(uint32_t)) {
        return -EINVAL;
    }

    void *data = (char *)buf + sizeof(uint32_t);

    if (data_len > 0 && data + data_len > end) {
        return -EINVAL;
    }

    return 0;
}
